<div id="alasan-retur-modal" class="fixed inset-0 z-[100] hidden items-center justify-center bg-black/40 p-4"><div class="absolute inset-0" onclick="closeAlasanReturModal()"></div><div class="relative w-full max-w-lg rounded-xl bg-white shadow-2xl"><div class="flex justify-between border-b border-outline-variant px-6 py-4"><h2 id="alasan-retur-title" class="text-xl font-semibold">Tambah Kategori Alasan Baru</h2><button type="button" onclick="closeAlasanReturModal()"><span class="material-symbols-outlined">close</span></button></div><form id="alasan-retur-form" method="POST" action="{{ route('master-alasan-retur.store') }}" class="space-y-4 p-6">@csrf<div><label class="mb-1 block font-semibold">Nama Alasan Kerusakan *</label><input id="alasan-retur-nama" name="nm_alasan_retur" required maxlength="100" placeholder="Contoh: Retak di Bagian Segel" class="w-full rounded-md border border-outline-variant px-3 py-2"><p class="mt-1 text-xs text-on-surface-variant">Ini yang bakal muncul jadi teks chip di form pembuatan retur.</p></div><div><label class="mb-1 block font-semibold">Status *</label><select id="alasan-retur-status" name="status_alasan_retur" required class="w-full rounded-md border border-outline-variant px-3 py-2"><option>AKTIF</option><option>TIDAK AKTIF</option></select><p class="mt-1 text-xs text-on-surface-variant">Cuma yang AKTIF yang muncul sebagai pilihan chip di form retur baru.</p></div><div class="flex justify-end gap-2 border-t border-outline-variant pt-4"><button type="button" onclick="closeAlasanReturModal()" class="rounded-md border px-4 py-2">Batal</button><button class="rounded-md bg-primary px-5 py-2 font-label-bold text-on-primary">Simpan</button></div></form></div></div><script>function openAlasanReturModal(){const m=document.getElementById('alasan-retur-modal');m.classList.remove('hidden');m.classList.add('flex');document.getElementById('alasan-retur-title').textContent='Tambah Kategori Alasan Baru';document.getElementById('alasan-retur-form').action='{{ route('master-alasan-retur.store') }}';document.getElementById('alasan-retur-form').querySelector('[name="_method"]')?.remove();document.getElementById('alasan-retur-nama').value='';document.getElementById('alasan-retur-status').value='AKTIF'}function closeAlasanReturModal(){const m=document.getElementById('alasan-retur-modal');m.classList.add('hidden');m.classList.remove('flex')}function editAlasanRetur(id,n,s){openAlasanReturModal();document.getElementById('alasan-retur-title').textContent='Edit Kategori Alasan';document.getElementById('alasan-retur-form').action='{{ url('/master-alasan-retur') }}/'+id;let m=document.getElementById('alasan-retur-form').querySelector('[name="_method"]');if(!m){m=document.createElement('input');m.type='hidden';m.name='_method';document.getElementById('alasan-retur-form').prepend(m)}m.value='PUT';document.getElementById('alasan-retur-nama').value=n||'';document.getElementById('alasan-retur-status').value=s||'AKTIF'}</script>